wikiPage.body:
&lt;div class=&quot;presentation navmenu&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;Acc&#232;s rapide aux tableaux r&#233;capitulatifs des dons&lt;a class=&quot;headeranchor&quot; id=&quot;Acc&#232;s_rapide_aux_tableaux_r&#233;capitulatifs_des_dons_0&quot; href=&quot;#Acc&#232;s_rapide_aux_tableaux_r&#233;capitulatifs_des_dons_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;table&gt;&lt;tr style=&quot;vertical-align: top; text-align: left&quot;&gt;&lt;td&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Dons.html&quot; title=&quot;Tableau r&#233;capitulatif des dons&quot;&gt;Dons g&#233;n&#233;raux&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Dons-Mythiques.html&quot; title=&quot;Dons mythiques&quot;&gt;Dons mythiques&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-Daudace-Et-De-Panache.html&quot; title=&quot;Dons d&amp;#39;audace et de panache&quot;&gt;Dons d&#39;audace et de panache&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-De-Combat.html&quot; title=&quot;Dons de combat&quot;&gt;Dons de combat&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-De-Cr&#233;ation-Dobjets.html&quot; title=&quot;Dons de cr&#233;ation d&amp;#39;objets&quot;&gt;Dons de cr&#233;ation d&#39;objets&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/td&gt;&lt;td&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-De-Critique.html&quot; title=&quot;Dons de critique&quot;&gt;Dons de critique&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-D&#233;cole.html&quot; title=&quot;Dons d&amp;#39;&#233;cole&quot;&gt;Dons d&#39;&#233;cole&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-D&#233;quipe.html&quot; title=&quot;Dons d&amp;#39;&#233;quipe&quot;&gt;Dons d&#39;&#233;quipe&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-De-Ma&#238;trise-Darme.html&quot; title=&quot;Dons de ma&#238;trise d&amp;#39;arme&quot;&gt;Dons de ma&#238;trise d&#39;arme&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Dons-De-Ma&#238;trise-Darmure.html&quot; title=&quot;Dons de ma&#238;trise d&amp;#39;armure&quot;&gt;d&#39;armure&lt;/a&gt;,&lt;br /&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-De-Ma&#238;trise-De-Bouclier.html&quot; title=&quot;Dons de ma&#238;trise de bouclier&quot;&gt;de bouclier&lt;/a&gt;, et &lt;a class=&quot;pagelink&quot; href=&quot;Dons-De-Ma&#238;trise-Dobjets.html&quot; title=&quot;Dons de ma&#238;trise d&amp;#39;objet&quot;&gt;d&#39;objet&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-De-Mal&#233;fice-Sanglant.html&quot; title=&quot;Dons de mal&#233;fice sanglant&quot;&gt;Dons de mal&#233;fice sanglant&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/td&gt;&lt;td&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-De-M&#233;tamagie.html&quot; title=&quot;Dons de m&#233;tamagie&quot;&gt;Dons de m&#233;tamagie&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-De-Regard.html&quot; title=&quot;dons de regard&quot;&gt;Dons de regard&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-De-R&#233;ussite.html&quot; title=&quot;Dons de r&#233;ussite&quot;&gt;Dons de r&#233;ussite&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-De-Spectacle.html&quot; title=&quot;Dons de spectacle&quot;&gt;Dons de spectacle&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-Dalignement.html&quot; title=&quot;Dons d&amp;#39;alignement&quot;&gt;Dons d&#39;alignement (PU)&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/td&gt;&lt;td&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-Dhistoire.html&quot; title=&quot;Dons d&amp;#39;histoire&quot;&gt;Dons d&#39;histoire (GC)&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-&#201;sot&#233;riques.html&quot; title=&quot;Dons &#233;sot&#233;riques&quot;&gt;Dons &#233;sot&#233;riques (PU)&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;&lt;ul&gt;
    &lt;li&gt;R&#232;gles g&#233;n&#233;rales&lt;/li&gt;
    &lt;ul&gt;
        &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons.html#DESCRIPTION&quot; title=&quot;Les dons&quot;&gt;format&lt;/a&gt;&lt;/li&gt;
        &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons.html#TYPES&quot; title=&quot;Les dons&quot;&gt;types de dons&lt;/a&gt;&lt;/li&gt;
    &lt;/ul&gt;
&lt;/ul&gt;
&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/div&gt;&lt;script&gt;
$(function () {
  $(&quot;tr.donpr&#233;requis0, tr.donpr&#233;requis1, tr.donpr&#233;requis2&quot;).hide();
  $(&quot;tr.donprincipal&quot;).bind(&quot;click&quot;, togglePrereq);
  $(&quot;tr.donpr&#233;requis0&quot;).bind(&quot;click&quot;, togglePrereq0);
  $(&quot;tr.donpr&#233;requis1&quot;).bind(&quot;click&quot;, togglePrereq1);
  $(&quot;tr.donprincipal&quot;).each(addPrereqIconIfNeeded);
  $(&quot;tr.donpr&#233;requis0&quot;).each(addPrereqIconIfNeeded0);
  $(&quot;tr.donpr&#233;requis1&quot;).each(addPrereqIconIfNeeded1);
  $(&quot;tr.donpr&#233;requis2&quot;).each(addPrereqIconIfNeeded2);
});
function togglePrereq() {
    let nodeImg = $(this).find(&quot;img&quot;);
      if (nodeImg.attr(&quot;src&quot;) == &quot;/Forum/themes/v2/sort_down.gif&quot;) {
            nodeImg.attr(&quot;src&quot;, &quot;/Forum/themes/v2/sort_up.gif&quot;);
      } else {
            nodeImg.attr(&quot;src&quot;, &quot;/Forum/themes/v2/sort_down.gif&quot;);
      };
    let node = $(this).next();
    while (node.length &gt; 0 &amp;&amp; node.hasClass(&quot;donpr&#233;requis0&quot;) || node.hasClass(&quot;donpr&#233;requis1&quot;) || node.hasClass(&quot;donpr&#233;requis2&quot;)) {
      node.toggle();
      if (node.hasClass(&quot;donpr&#233;requis1&quot;) || node.hasClass(&quot;donpr&#233;requis2&quot;)) {
            node.toggle();
      };
      node = node.next();
    }
}
function togglePrereq0() {
    let nodeImg = $(this).find(&quot;img&quot;);
      if (nodeImg.attr(&quot;src&quot;) == &quot;/Forum/themes/v2/sort_down.gif&quot;) {
            nodeImg.attr(&quot;src&quot;, &quot;/Forum/themes/v2/sort_up.gif&quot;);
      } else {
            nodeImg.attr(&quot;src&quot;, &quot;/Forum/themes/v2/sort_down.gif&quot;);
      };
    let node = $(this).next();
    while (node.length &gt; 0 &amp;&amp; node.hasClass(&quot;donpr&#233;requis1&quot;) || node.hasClass(&quot;donpr&#233;requis2&quot;)) {
      node.toggle();
      if (node.hasClass(&quot;donpr&#233;requis2&quot;)) {
            node.toggle();
      };
      node = node.next();
    }
}
function togglePrereq1() {
    let nodeImg = $(this).find(&quot;img&quot;);
      if (nodeImg.attr(&quot;src&quot;) == &quot;/Forum/themes/v2/sort_down.gif&quot;) {
            nodeImg.attr(&quot;src&quot;, &quot;/Forum/themes/v2/sort_up.gif&quot;);
      } else {
            nodeImg.attr(&quot;src&quot;, &quot;/Forum/themes/v2/sort_down.gif&quot;);
      };
    let node = $(this).next();
    while (node.length &gt; 0 &amp;&amp; node.hasClass(&quot;donpr&#233;requis2&quot;)) {
      node.toggle();
      node = node.next();
    }
}
function addPrereqIconIfNeeded() {
	let next = $(this).next();
	if (next.length &gt; 0 &amp;&amp; next.hasClass(&quot;donpr&#233;requis0&quot;)) {
	  let icon = document.createElement(&quot;img&quot;);
	  icon.src = &quot;/Forum/themes/v2/sort_down.gif&quot;;
	  icon.style = &quot;float:right;margin-top: 3px;&quot;;
	  icon.title = &quot;Cliquez pour afficher les dons qui d&#233;coulent de celui-ci.&quot;;
	  $(this).children(&quot;td&quot;).first().append($(icon));
	}
}
function addPrereqIconIfNeeded0() {
	let next = $(this).next();
	if (next.length &gt; 0 &amp;&amp; next.hasClass(&quot;donpr&#233;requis1&quot;)) {
	  let icon = document.createElement(&quot;img&quot;);
	  icon.src = &quot;/Forum/themes/v2/sort_down.gif&quot;;
	  icon.style = &quot;float:right;margin-top: 3px;&quot;;
	  icon.title = &quot;Cliquez pour afficher les dons qui d&#233;coulent de celui-ci.&quot;;
	  $(this).children(&quot;td&quot;).first().append($(icon));
	}
}
function addPrereqIconIfNeeded1() {
	let next = $(this).next();
	if (next.length &gt; 0 &amp;&amp; next.hasClass(&quot;donpr&#233;requis2&quot;)) {
	  let icon = document.createElement(&quot;img&quot;);
	  icon.src = &quot;/Forum/themes/v2/sort_down.gif&quot;;
	  icon.style = &quot;float:right;margin-top: 3px;&quot;;
	  icon.title = &quot;Cliquez pour afficher les dons qui d&#233;coulent de celui-ci.&quot;;
	  $(this).children(&quot;td&quot;).first().append($(icon));
	}
	if (next.length &gt; 0 &amp;&amp; next.hasClass(&quot;donpr&#233;requis0&quot;)) {
	  $(this).children(&quot;td&quot;).css(&quot;border-bottom&quot;, &quot;1px solid black&quot;);
	}
}
function addPrereqIconIfNeeded2() {
	if (next.length &gt; 0 &amp;&amp; next.hasClass(&quot;donpr&#233;requis0&quot;) || next.hasClass(&quot;donpr&#233;requis1&quot;)) {
	  $(this).children(&quot;td&quot;).css(&quot;border-bottom&quot;, &quot;1px solid black&quot;);
	}
}
&lt;/script&gt;Les dons d’&#233;quipe offrent des bonus importants, mais ils ne fonctionnent que sous certaines conditions. Dans la plupart des cas, ils n&#233;cessitent la pr&#233;sence d’un alli&#233; poss&#233;dant &#233;galement le don en question et sa pr&#233;sence &#224; un endroit pr&#233;cis du champ de bataille. Les dons d’&#233;quipe ne donnent aucun bonus si les conditions pr&#233;cis&#233;es ne sont pas remplies. Notez que les alli&#233;s qui sont &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Paralys&#233;.html&quot; title=&quot;Paralys&#233;&quot;&gt;paralys&#233;s&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#&#201;tourdi.html&quot; title=&quot;&#201;tourdi&quot;&gt;&#233;tourdis&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Inconscient.html&quot; title=&quot;Inconscient&quot;&gt;inconscients&lt;/a&gt; ou incapables d’agir pour une raison ou une autre ne permettent pas de remplir les conditions de ces dons.&lt;br /&gt;&lt;br /&gt;Les chevaliers, les chasseurs et les inquisiteurs poss&#232;dent des pouvoirs de classe sp&#233;ciaux qui leur permettent d’utiliser les dons de travail en &#233;quipe m&#234;me si leurs alli&#233;s ne les poss&#232;dent pas.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Les dons marqu&#233;s d&#39;un ast&#233;risque (*) sont des dons de combat.&lt;/i&gt;
&lt;center&gt;
&lt;table CLASS=&quot;tablo toutgauche&quot;&gt;&lt;caption&gt;Tableau r&#233;capitulatif des dons d&#39;&#233;quipe&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td WIDTH=&quot;25%&quot;&gt;Dons&lt;/td&gt;&lt;td WIDTH=&quot;3%&quot;&gt;Src&lt;/td&gt;&lt;td WIDTH=&quot;34%&quot;&gt;Conditions&lt;/td&gt;&lt;td WIDTH=&quot;38%&quot;&gt;Avantages&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#192;-Labri.html&quot; title=&quot;&#192; l&amp;#39;abri&quot;&gt;&#192; l&#39;abri&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJRA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;Utiliser le r&#233;sultat d&#39;un alli&#233; pour son propre jet de sauvegarde&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt donpr&#233;requis0&quot;&gt;&lt;td&gt;&amp;emsp;&lt;a class=&quot;pagelink&quot; href=&quot;Science-De-Labri.html&quot; title=&quot;Science de l&amp;#39;abri&quot;&gt;Science de l&#39;abri&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&#192; l&#39;abri&lt;/td&gt;&lt;td&gt;Quand le personnage utilise &#192; l&#39;abri, un alli&#233; poss&#233;dant esquive totale ou esquive surnaturelle re&#231;oit une partie des d&#233;g&#226;ts&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier alt donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Acclamation-Incessante.html&quot; title=&quot;Acclamation incessante&quot;&gt;Acclamation incessante&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Halfelin.html&quot; title=&quot;Les halfelins&quot;&gt;Halfelin&lt;/a&gt;, traits raicuax chance des halfelins et sans peur&lt;/td&gt;&lt;td&gt;+1 aux jets de sauvegarde qui passe &#224; +3 contre la peur lorsqu&#39;adjacent &#224; un alli&#233; avec ce don&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Attaque-Dencerclement.html&quot; title=&quot;Attaque d&amp;#39;encerclement&quot;&gt;Attaque d&#39;encerclement&lt;/a&gt;*&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MPNJ&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Esquive.html&quot; title=&quot;Esquive&quot;&gt;Esquive&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Souplesse-Du-Serpent.html&quot; title=&quot;Souplesse du serpent&quot;&gt;Souplesse du serpent&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Bonusdebasealattaque.html&quot; title=&quot;BBA&quot;&gt;BBA&lt;/a&gt; +3&lt;/td&gt;&lt;td&gt;Aux c&#244;t&#233;s d&#39;un alli&#233;, le personnage sait engager le combat contre des ennemis de grande taille qui &#233;prouveront alors des difficult&#233;s &#224; r&#233;pliquer contre ces deux assaillants.&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier alt donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Attaquer-En-Meute.html&quot; title=&quot;Attaquer en meute&quot;&gt;Attaquer en meute&lt;/a&gt;*&lt;/td&gt;&lt;td&gt;&lt;sup&gt;AG&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Bonusdebasealattaque.html&quot; title=&quot;BBA&quot;&gt;BBA&lt;/a&gt; +1&lt;/td&gt;&lt;td&gt;Une attaque alli&#233;e permet au personnage de faire un pas de 1,50 m&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Barrage-De-Styles.html&quot; title=&quot;Barrage de styles&quot;&gt;Barrage de styles&lt;/a&gt;*&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Bonusdebasealattaque.html&quot; title=&quot;BBA&quot;&gt;BBA&lt;/a&gt; +1, &lt;a class=&quot;pagelink&quot; href=&quot;Humain.html&quot; title=&quot;Les humains&quot;&gt;humain&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Les alli&#233;s adjacents diff&#233;rents avec ce don obtiennent un bonus cumulatif de +1 (maximum +4) aux manœuvres offensives&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier alt donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cachette-Commune.html&quot; title=&quot;Cachette commune&quot;&gt;Cachette commune&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CM&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Arme-En-Main.html&quot; title=&quot;Arme en main&quot;&gt;Arme en main&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Bonusdebasealattaque.html&quot; title=&quot;BBA&quot;&gt;BBA&lt;/a&gt; +1, 1 rang en &lt;a class=&quot;pagelink&quot; href=&quot;Escamotage.html&quot; title=&quot;Escamotage&quot;&gt;Escamotage&lt;/a&gt;, trait racial &lt;a class=&quot;pagelink&quot; href=&quot;Homme-Rat-(Race).html#Traits_raciaux_standards_7&quot; title=&quot;Les hommes-rats&quot;&gt;regroupement&lt;/a&gt;&lt;/td&gt;&lt;td&gt;R&#233;cup&#232;re rapidement des objets port&#233;s par les alli&#233;s&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cavalerie-En-Formation.html&quot; title=&quot;Cavalerie en formation&quot;&gt;Cavalerie en formation&lt;/a&gt;*&lt;/td&gt;&lt;td&gt;&lt;sup&gt;AG&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Combat-Mont&#233;.html&quot; title=&quot;Combat mont&#233;&quot;&gt;Combat mont&#233;&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Le personnage partage sa case avec d&#39;autres montures et peut charger &#224; travers une case occup&#233;e par une monture alli&#233;e&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier alt donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Charge-Coordonn&#233;e.html&quot; title=&quot;Charge coordonn&#233;e&quot;&gt;Charge coordonn&#233;e&lt;/a&gt;*&lt;/td&gt;&lt;td&gt;&lt;sup&gt;AG&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Deux &lt;a class=&quot;pagelink&quot; href=&quot;Dons.html#DONEQUIPE&quot; title=&quot;Les dons&quot;&gt;dons d&#39;&#233;quipe&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Bonusdebasealattaque.html&quot; title=&quot;BBA&quot;&gt;BBA&lt;/a&gt; +10&lt;/td&gt;&lt;td&gt;Le personnage peut charger le m&#234;me adversaire que son alli&#233;&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Charge-De-Diversion.html&quot; title=&quot;Charge de diversion&quot;&gt;Charge de diversion&lt;/a&gt;*&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;Quand un alli&#233; poss&#233;dant ce don charge, le personnage gagne un bonus de +2 aux jets d&#39;attaque contre la cr&#233;ature charg&#233;e&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier alt donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Charge-De-La-Horde.html&quot; title=&quot;Charge de la horde&quot;&gt;Charge de la horde&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Bonusdebasealattaque.html&quot; title=&quot;BBA&quot;&gt;BBA&lt;/a&gt; +1, &lt;a class=&quot;pagelink&quot; href=&quot;Demi-Orque.html&quot; title=&quot;Les demi-orques&quot;&gt;demi-orque&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Orque-(Race).html&quot; title=&quot;Les orques&quot;&gt;orque&lt;/a&gt;&lt;/td&gt;&lt;td&gt;+2 &#224; l&#39;attaque et aux d&#233;g&#226;ts lors d&#39;une charge avec un alli&#233;&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chœur-De-Lames.html&quot; title=&quot;Chœur de lames&quot;&gt;Chœur de lames&lt;/a&gt;*&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;Acc&#232;s au bonus &#224; l&#39;attaque d&#39;un alli&#233; haineux, ainsi qu&#39;&#224; ses formations martiales raciales&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier alt donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cible-Dopportunit&#233;.html&quot; title=&quot;Cible d&amp;#39;opportunit&#233;&quot;&gt;Cible d&#39;opportunit&#233;&lt;/a&gt;*&lt;/td&gt;&lt;td&gt;&lt;sup&gt;AG&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tir-&#192;-Bout-Portant.html&quot; title=&quot;Tir &#224; bout portant&quot;&gt;Tir &#224; bout portant&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Bonusdebasealattaque.html&quot; title=&quot;BBA&quot;&gt;BBA&lt;/a&gt; +6&lt;/td&gt;&lt;td&gt;Quand un alli&#233; r&#233;ussit une attaque &#224; distance, le personnage peut faire une attaque par une action imm&#233;diate&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Conjonction-Extraplanaire.html&quot; title=&quot;Conjonction extraplanaire&quot;&gt;Conjonction extraplanaire&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;N&#39;importe quel pouvoir magique racial, type &lt;a class=&quot;pagelink&quot; href=&quot;Type-Ext&#233;rieur.html&quot; title=&quot;Ext&#233;rieur&quot;&gt;ext&#233;rieur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Augmente de 2 le DD d&#39;un pouvoir magique racial &#224; proximit&#233; d&#39;un alli&#233; avec ce don et le m&#234;me pouvoir magique&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier alt donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Connexion-Mentale-Alien.html&quot; title=&quot;Connexion mentale alien&quot;&gt;Connexion mentale alien&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Andro&#239;de-(Race).html&quot; title=&quot;Les andro&#239;des&quot;&gt;Andro&#239;de&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Kasatha-(Race).html&quot; title=&quot;Les kasathas&quot;&gt;kasatha&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Lashunta-(Race).html&quot; title=&quot;Les lashuntas&quot;&gt;lashunta&lt;/a&gt;, ou &lt;a class=&quot;pagelink&quot; href=&quot;Triaxien-(Race).html&quot; title=&quot;Les triaxiens&quot;&gt;triaxien&lt;/a&gt;&lt;/td&gt;&lt;td&gt;+4 aux jets de sauvegarde contre les effets mentaux et les scrutations&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Contresort-Coop&#233;ratif.html&quot; title=&quot;Contresort coop&#233;ratif&quot;&gt;Contresort coop&#233;ratif&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;5 rangs en &lt;a class=&quot;pagelink&quot; href=&quot;Art-De-La-Magie.html&quot; title=&quot;Art de la magie&quot;&gt;Art de la magie&lt;/a&gt;, pouvoir magique racial &#233;mulant un sort de 1er niveau ou sup&#233;rieur&lt;/td&gt;&lt;td&gt;Plus d&#39;options de contresort lorsque le personnage et un alli&#233; avec ce don pr&#233;parent tous deux l&#39;action&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier alt donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Convergence-Magique-&#201;lev&#233;e.html&quot; title=&quot;Convergence magique &#233;lev&#233;e&quot;&gt;Convergence magique &#233;lev&#233;e&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;N&#39;importe quel &lt;a class=&quot;pagelink&quot; href=&quot;Dons.html#DONMETAMAGIE&quot; title=&quot;Les dons&quot;&gt;don de m&#233;tamagie&lt;/a&gt;, 7 rangs en &lt;a class=&quot;pagelink&quot; href=&quot;Art-De-La-Magie.html&quot; title=&quot;Art de la magie&quot;&gt;Art de la magie&lt;/a&gt;, capacit&#233; &#224; lancer des sorts de 2e niveau, &lt;a class=&quot;pagelink&quot; href=&quot;Humain.html&quot; title=&quot;Les humains&quot;&gt;humain&lt;/a&gt; (garundi)&lt;/td&gt;&lt;td&gt;Applique spontan&#233;ment des dons de m&#233;tamagie sans d&#233;penser d&#39;emplacements de sorts sup&#233;rieurs ou augmenter le temps d&#39;incantation si des alli&#233;s se pr&#233;parent &#224; lancer le m&#234;me sort&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Coordination-Opportune.html&quot; title=&quot;Coordination opportune&quot;&gt;Coordination opportune&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;UI&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;+1 aux jets d&#39;attaque et aux tests de comp&#233;tence des actions pr&#233;par&#233;es d&#233;clench&#233;es par des alli&#233;s&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier alt donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Coup-De-Focalisation.html&quot; title=&quot;Coup de focalisation&quot;&gt;Coup de focalisation&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Discipline-Hobgobeline.html&quot; title=&quot;Discipline hobgobeline&quot;&gt;Discipline hobgobeline&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Hobgobelin-(Race).html&quot; title=&quot;Les hobgobelins&quot;&gt;hobgobelin&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Inflige des d&#233;g&#226;ts pour lib&#233;rer un alli&#233; d&#39;un effet mental&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Coup-Pr&#233;cis.html&quot; title=&quot;Coup pr&#233;cis&quot;&gt;Coup pr&#233;cis&lt;/a&gt;*&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJRA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Dexterite.html&quot; title=&quot;Dex&quot;&gt;Dex&lt;/a&gt; 13, &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Bonusdebasealattaque.html&quot; title=&quot;BBA&quot;&gt;BBA&lt;/a&gt; +1&lt;/td&gt;&lt;td&gt;Inflige +1d6 points de pr&#233;cision avec les attaques au corps &#224; corps&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier alt donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Couple-Dopportunistes.html&quot; title=&quot;Couple d&amp;#39;opportunistes&quot;&gt;Couple d&#39;opportunistes&lt;/a&gt;*&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJRA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;Bonus de +4 aux attaques d&#39;opportunit&#233;&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;fenses-Coordonn&#233;es.html&quot; title=&quot;D&#233;fenses coordonn&#233;es&quot;&gt;D&#233;fenses coordonn&#233;es&lt;/a&gt;*&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJRA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;Bonus de +2 au DMD&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier alt donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;ferlante-Coordonn&#233;e.html&quot; title=&quot;D&#233;ferlante coordonn&#233;e&quot;&gt;D&#233;ferlante coordonn&#233;e&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;5 rangs en &lt;a class=&quot;pagelink&quot; href=&quot;Art-De-La-Magie.html&quot; title=&quot;Art de la magie&quot;&gt;Art de la magie&lt;/a&gt;, n&#39;importe quel pouvoir magique racial&lt;/td&gt;&lt;td&gt;Exclut les alli&#233;s avec ce don des zones d&#39;effet des sorts et capacit&#233;s&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;samor&#231;age-Coop&#233;ratif.html&quot; title=&quot;D&#233;samor&#231;age coop&#233;ratif&quot;&gt;D&#233;samor&#231;age coop&#233;ratif&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;UI&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;1 rang en &lt;a class=&quot;pagelink&quot; href=&quot;Sabotage.html&quot; title=&quot;Sabotage&quot;&gt;Sabotage&lt;/a&gt;, capacit&#233; de classe &lt;a class=&quot;pagelink&quot; href=&quot;Roublard.html#RECHERCHEDESPIEGES&quot; title=&quot;Le roublard&quot;&gt;recherche des pi&#232;ges&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Un alli&#233; adjacent peut faire un second test de Sabotage par une action imm&#233;diate&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier alt donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dos-&#192;-Dos.html&quot; title=&quot;Dos &#224; dos&quot;&gt;Dos &#224; dos&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;AG&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;3 rangs en &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt;&lt;/td&gt;&lt;td&gt;+2 &#224; la CA contre les adversaires qui prennent le personnage en tenaille&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;donpr&#233;requis0&quot;&gt;&lt;td&gt;&amp;emsp;&lt;a class=&quot;pagelink&quot; href=&quot;Science-Du-Combat-Dos-&#192;-Dos.html&quot; title=&quot;Science du combat dos &#224; dos&quot;&gt;Science du combat dos &#224; dos&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;AG&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Dos &#224; dos, 5 rangs en Perception&lt;/td&gt;&lt;td&gt;Donne un bonus de +2 &#224; la CA &#224; un alli&#233; adjacent contre les adversaires qui le prennent en tenaille&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Double-Croc-En-Jambe.html&quot; title=&quot;Double croc-en-jambe&quot;&gt;Double croc-en-jambe&lt;/a&gt;*&lt;/td&gt;&lt;td&gt;&lt;sup&gt;AG&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;Quand le personnage fait un croc-en-jambe &#224; un adversaire que menace un alli&#233;, il lance deux fois le d&#233; et prend le meilleur r&#233;sultat&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier alt donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;change-De-Place.html&quot; title=&quot;&#201;change de place&quot;&gt;&#201;change de place&lt;/a&gt;*&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJRA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;Changer de place avec un alli&#233; adjacent&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;donpr&#233;requis0&quot;&gt;&lt;td&gt;&amp;emsp;&lt;a class=&quot;pagelink&quot; href=&quot;Science-De-L&#233;change-De-Place.html&quot; title=&quot;Science de l&amp;#39;&#233;change de place&quot;&gt;Science de l&#39;&#233;change de place&lt;/a&gt;*&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&#201;change de place&lt;/td&gt;&lt;td&gt;Quand le personnage utilise &#201;change de place, son alli&#233; peut &#234;tre plus petit ou plus grand que lui et son d&#233;placement ne provoque pas d&#39;attaque d&#39;opportunit&#233;&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;chappatoire.html&quot; title=&quot;&#201;chappatoire&quot;&gt;&#201;chappatoire&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;AG&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;Le personnage ne provoque pas d&#39;attaque d&#39;opportunit&#233; quand il passe dans une case adjacente &#224; un alli&#233;&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier alt donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;chos-Du-Premier-Monde.html&quot; title=&quot;&#201;chos du Premier Monde&quot;&gt;&#201;chos du Premier Monde&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;2 rangs en &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (nature), sous-type &lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Gnome.html&quot; title=&quot;Gnome (sous-type)&quot;&gt;gnome&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Gain d&#39;une RD 2/fer froid et est consid&#233;r&#233; comme une f&#233;e plut&#244;t qu&#39;un humano&#239;de &#224; proximit&#233; d&#39;alli&#233;s avec ce don&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;clat-Amplifi&#233;.html&quot; title=&quot;&#201;clat amplifi&#233;&quot;&gt;&#201;clat amplifi&#233;&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Aasimar-(Race).html&quot; title=&quot;Les aasimars&quot;&gt;Aasimar&lt;/a&gt;, pouvoir magique racial &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lumi&#232;re-Du-Jour.html&quot; title=&quot;Lumi&#232;re du jour&quot;&gt;lumi&#232;re du jour&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;&#201;met une aura de lumi&#232;re &#224; proximit&#233; d&#39;un alli&#233; qui poss&#232;de ce don&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier alt donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ensemble.html&quot; title=&quot;Ensemble&quot;&gt;Ensemble&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;AM&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;5 rangs en &lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentation.html&quot; title=&quot;Repr&#233;sentation&quot;&gt;Repr&#233;sentation&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Les artistes voisins peuvent aider le personnage &#224; faire son test de Repr&#233;sentation&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Entrem&#234;ler-Les-Explosions-Composites.html&quot; title=&quot;Entrem&#234;ler les explosions composites&quot;&gt;Entrem&#234;ler les explosions composites&lt;/a&gt;*&lt;/td&gt;&lt;td&gt;&lt;sup&gt;AO&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Capacit&#233; de classe &lt;a class=&quot;pagelink&quot; href=&quot;Cin&#233;tiste.html#EXPLOSIONCINETIQUE&quot; title=&quot;Le cin&#233;tiste&quot;&gt;explosion cin&#233;tique&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Travail en &#233;quipe pour d&#233;cha&#238;ner une explosion composite&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier alt donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;quipe-Dartillerie.html&quot; title=&quot;&#201;quipe d&amp;#39;artillerie&quot;&gt;&#201;quipe d&#39;artillerie&lt;/a&gt;*&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Maniement des &lt;a class=&quot;pagelink&quot; href=&quot;Arbal&#232;te-L&#233;g&#232;re-(Arme).html&quot; title=&quot;Arbal&#232;te l&#233;g&#232;re&quot;&gt;arbal&#232;tes l&#233;g&#232;res&lt;/a&gt;, des &lt;a class=&quot;pagelink&quot; href=&quot;Arbal&#232;te-Lourde-(Arme).html&quot; title=&quot;Arbal&#232;te lourde&quot;&gt;arbal&#232;tes lourdes&lt;/a&gt; ou des &lt;a class=&quot;pagelink&quot; href=&quot;Mousquet-(Arme).html&quot; title=&quot;Mousquet&quot;&gt;mousquets&lt;/a&gt; ; &lt;a class=&quot;pagelink&quot; href=&quot;Petites-Et-Grandes-Cr&#233;atures#Tableautailles.html&quot; title=&quot;taille P&quot;&gt;taille P&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Petites-Et-Grandes-Cr&#233;atures#Tableautailles.html&quot; title=&quot;taille M&quot;&gt;M&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Un alli&#233; avec ce don peut aider &#224; charger et tirer avec une arbal&#232;te l&#233;g&#232;re, une arbal&#232;te lourde ou un mousquet de taille G&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;quipe-De-Pickpockets.html&quot; title=&quot;&#201;quipe de pickpockets&quot;&gt;&#201;quipe de pickpockets&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;AG&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;1 rang en &lt;a class=&quot;pagelink&quot; href=&quot;Bluff.html&quot; title=&quot;Bluff&quot;&gt;Bluff&lt;/a&gt;, 1 rang en &lt;a class=&quot;pagelink&quot; href=&quot;Escamotage.html&quot; title=&quot;Escamotage&quot;&gt;Escamotage&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Quand un alli&#233; r&#233;ussit un test de Bluff, le personnage peut fouiller dans la poche de la victime par une action imm&#233;diate&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier alt donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;quipe-De-Tueurs-De-G&#233;ants.html&quot; title=&quot;&#201;quipe de tueurs de g&#233;ants&quot;&gt;&#201;quipe de tueurs de g&#233;ants&lt;/a&gt;*&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Dexterite.html&quot; title=&quot;La Dext&#233;rit&#233;&quot;&gt;Dex&lt;/a&gt; 13, &lt;a class=&quot;pagelink&quot; href=&quot;Esquive.html&quot; title=&quot;Esquive&quot;&gt;Esquive&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Souplesse-Du-Serpent.html&quot; title=&quot;Souplesse du serpent&quot;&gt;Souplesse du serpent&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Bonusdebasealattaque.html&quot; title=&quot;BBA&quot;&gt;BBA&lt;/a&gt; +4, trait racial entra&#238;nement d&#233;fensif&lt;/td&gt;&lt;td&gt;Attaque un g&#233;ant par une action imm&#233;diate lorsque son attaque d&#39;opportunit&#233; rate un alli&#233; avec ce don&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Esprit-D&#233;quipe.html&quot; title=&quot;Esprit d&amp;#39;&#233;quipe&quot;&gt;Esprit d&#39;&#233;quipe&lt;/a&gt;*&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CM&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;Duplique les bonus de moral dont b&#233;n&#233;ficient les alli&#233;s&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier alt donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Esprit-Unique.html&quot; title=&quot;Esprit unique&quot;&gt;Esprit unique&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Vigilance.html&quot; title=&quot;Vigilance&quot;&gt;Vigilance&lt;/a&gt;, 3 rangs en &lt;a class=&quot;pagelink&quot; href=&quot;Psychologie.html&quot; title=&quot;Psychologie&quot;&gt;Psychologie&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Humain.html&quot; title=&quot;Les humains&quot;&gt;humain&lt;/a&gt; (vudrain)&lt;/td&gt;&lt;td&gt;&#201;vite les malus dus &#224; l&#39;&#233;tat pris au d&#233;pourvu, aveugl&#233; ou en combattant des ennemis invisibles si adjacent &#224; un alli&#233; avec ce don&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;ventration-&#192;-Deux.html&quot; title=&quot;&#201;ventration &#224; deux&quot;&gt;&#201;ventration &#224; deux&lt;/a&gt;*&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CM&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Pouvoir &lt;a class=&quot;pagelink&quot; href=&quot;&#201;ventration-(Capacit&#233;).html&quot; title=&quot;&#201;ventration (Ext)&quot;&gt;&#233;ventration&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Troll.html&quot; title=&quot;Troll&quot;&gt;troll&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Utilise l&#39;&#233;ventration beaucoup plus facilement&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier alt donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Flot-Des-&#201;l&#233;ments.html&quot; title=&quot;Flot des &#233;l&#233;ments&quot;&gt;Flot des &#233;l&#233;ments&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Capacit&#233; &#224; lancer des sorts ; &lt;a class=&quot;pagelink&quot; href=&quot;Ifrit-(Race).html&quot; title=&quot;Les ifrits&quot;&gt;ifrit&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Ondin-(Race).html&quot; title=&quot;Les ondins&quot;&gt;ondin&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Or&#233;ade-(Race).html&quot; title=&quot;Les or&#233;ades&quot;&gt;or&#233;ade&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Sylphe-(Race).html&quot; title=&quot;Les sylphes&quot;&gt;sylphe&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Modifie tous ou une partie des d&#233;g&#226;ts d&#39;un sort pour correspondre &#224; la race d&#39;un alli&#233; adjacent avec ce don&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Forteresse-Vivante.html&quot; title=&quot;Forteresse vivante&quot;&gt;Forteresse vivante&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Nain.html&quot; title=&quot;Les nains&quot;&gt;Nain&lt;/a&gt;, trait racial robuste&lt;/td&gt;&lt;td&gt;Les bonus raciaux aux jets de sauvegarde contre les sorts et pouvoirs magiques augmentent de 2 &#224; proximit&#233; d&#39;un alli&#233; avec ce don&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier alt donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Frappe-De-L&#233;clipse.html&quot; title=&quot;Frappe de l&amp;#39;&#233;clipse&quot;&gt;Frappe de l&#39;&#233;clipse&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tieffelin-(Race).html&quot; title=&quot;Les tieffelins&quot;&gt;Tieffelin&lt;/a&gt;, pouvoir magique racial &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;T&#233;n&#232;bres.html&quot; title=&quot;T&#233;n&#232;bres&quot;&gt;t&#233;n&#232;bres&lt;/a&gt;&lt;/i&gt;&lt;/td&gt;&lt;td&gt;Effectue une frappe de l&#39;&#233;clipse pour aveugler une cible en prenant en tenaille gr&#226;ce &#224; un alli&#233; avec ce don&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fr&#233;n&#233;sie-Martiale.html&quot; title=&quot;Fr&#233;n&#233;sie martiale&quot;&gt;Fr&#233;n&#233;sie martiale&lt;/a&gt;*&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Cha&quot;&gt;Cha&lt;/a&gt; 13, capacit&#233; de classe &lt;a class=&quot;pagelink&quot; href=&quot;Barbare.html#RAGE&quot; title=&quot;Le barbare&quot;&gt;rage de berserker&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Quand un alli&#233; est proche du personnage, le malus &#224; la CA de sa rage est r&#233;duit de 2.&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier alt donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gang-De-Brutes.html&quot; title=&quot;Gang de brutes&quot;&gt;Gang de brutes&lt;/a&gt;*&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Demi-Orque.html&quot; title=&quot;Les demi-orques&quot;&gt;Demi-orque&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Les alli&#233;s avec ce dont obtiennent un +2 aux tests de BMO lorsque le personnage en rate un&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Grande-Tenaille.html&quot; title=&quot;Grande tenaille&quot;&gt;Grande tenaille&lt;/a&gt;*&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJRA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Bonusdebasealattaque.html&quot; title=&quot;BBA&quot;&gt;BBA&lt;/a&gt; +4&lt;/td&gt;&lt;td&gt;Bonus de +4 aux jets d&#39;attaque en cas de prise en tenaille&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier alt donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Groupe-Embusqu&#233;.html&quot; title=&quot;Groupe embusqu&#233;&quot;&gt;Groupe embusqu&#233;&lt;/a&gt;*&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Bonusdebasealattaque.html&quot; title=&quot;BBA&quot;&gt;BBA&lt;/a&gt; +1, &lt;a class=&quot;pagelink&quot; href=&quot;Kobold-(Race).html&quot; title=&quot;Les kobolds&quot;&gt;Kobold&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Si le personnage et son alli&#233; peuvent agir lors du round de surprise, ils peuvent effectuer une action simple et de mouvement&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gu&#233;rison-Partag&#233;e.html&quot; title=&quot;Gu&#233;rison partag&#233;e&quot;&gt;Gu&#233;rison partag&#233;e&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Capacit&#233; &#224; obtenir un &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#PACTEAVECLANATURE&quot; title=&quot;Le druide&quot;&gt;compagnon animal&lt;/a&gt;, un &lt;a class=&quot;pagelink&quot; href=&quot;Conjurateur.html#EIDOLON&quot; title=&quot;Le conjurateur (aussi appel&#233; invocateur)&quot;&gt;eidolon&lt;/a&gt;, un &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html#PACTEMAGIQUE&quot; title=&quot;Le magicien&quot;&gt;familier&lt;/a&gt; ou une &lt;a class=&quot;pagelink&quot; href=&quot;Chevalier.html#MONTURE&quot; title=&quot;Le chevalier&quot;&gt;monture sp&#233;ciale&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Le personnage partage sa gu&#233;rison avec son compagnon&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier alt donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Horde-F&#233;roce.html&quot; title=&quot;Horde f&#233;roce&quot;&gt;Horde f&#233;roce&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Orque-(Race).html&quot; title=&quot;Les orques&quot;&gt;Orque&lt;/a&gt;, trait racial f&#233;rocit&#233;&lt;/td&gt;&lt;td&gt;Bonus de moral de +2 aux jets d&#39;attaque lorsque le personnage et un alli&#233; avec ce don sont &#224; la moiti&#233; de leurs pvs ou moins&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Imitation-Des-Semblables.html&quot; title=&quot;Imitation des semblables&quot;&gt;Imitation des semblables&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;8 rangs en &lt;a class=&quot;pagelink&quot; href=&quot;Bluff.html&quot; title=&quot;Bluff&quot;&gt;Bluff&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Gnome.html&quot; title=&quot;Les gnomes&quot;&gt;gnome&lt;/a&gt;, trait racial magie gnome&lt;/td&gt;&lt;td&gt;Gain d&#39;un camouflage de 20 % lorsque le personnage est adjacent &#224; un alli&#233; avec ce don&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier alt donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Interception-De-Charge.html&quot; title=&quot;Interception de charge&quot;&gt;Interception de charge&lt;/a&gt;*&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;Par une action imm&#233;diate, le personnage se d&#233;place &#224; sa vitesse normale pour intercepter un ennemi qui charge&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Intimidation-De-Meute.html&quot; title=&quot;Intimidation de meute&quot;&gt;Intimidation de meute&lt;/a&gt;*&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Demi-Orque.html&quot; title=&quot;Les demi-orques&quot;&gt;Demi-orque&lt;/a&gt;, trait racial intimidant&lt;/td&gt;&lt;td&gt;+2 aux tests d&#39;Intimidation visant &#224; d&#233;moraliser pour chaque alli&#233; avec ce don dans un rayon de 9 m&#232;tres&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier alt donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lames-Au-Dessus-Et-En-Dessous.html&quot; title=&quot;Lames au-dessus et en dessous&quot;&gt;Lames au-dessus et en dessous&lt;/a&gt;*&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Bonusdebasealattaque.html&quot; title=&quot;BBA&quot;&gt;BBA&lt;/a&gt; +6&lt;/td&gt;&lt;td&gt;Prend en tenaille avec un alli&#233; d&#39;une cat&#233;gorie de taille diff&#233;rente depuis n&#39;importe quelle position&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Boomerang.html&quot; title=&quot;Lancer boomerang&quot;&gt;Lancer boomerang&lt;/a&gt;*&